use serde_json::{Value, from_str, to_string};
use std::iter::FromIterator;

pub fn solve(input: Value) -> Value {
    let bytes = input.as_array().expect("Input must be an array of bytes").iter()
        .map(|b| b.as_i64().expect("Array elements must be integers"))
        .map(|b| format!("{:02x}", b as u8))
        .collect::<Vec<String>>()
        .join("");

    Value::String(bytes)
}
